import{_ as t,c as e,a2 as a,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百五十八章 如来会讲解什么？","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/158第一百五十八章 如来会讲解什么.md","filePath":"meditation/巴利文大藏经/158第一百五十八章 如来会讲解什么.md"}'),_={name:"meditation/巴利文大藏经/158第一百五十八章 如来会讲解什么.md"};function r(n,p,i,s,d,c){return o(),e("div",null,p[0]||(p[0]=[a('<h1 id="第一百五十八章-如来会讲解什么" tabindex="-1">第一百五十八章 如来会讲解什么？ <a class="header-anchor" href="#第一百五十八章-如来会讲解什么" aria-label="Permalink to &quot;第一百五十八章 如来会讲解什么？&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部16相应12经/死后经(迦叶相应/因缘篇/如来记说)</p><p>有个时候，迦叶尊者与舍利弗尊者住在波罗奈的鹿野苑，有一天傍晚，舍利弗尊者静坐完毕后，就来到迦叶尊者的住处，他与迦叶尊者互相问候后，就在一旁坐下，舍利弗尊者对迦叶尊者说：“迦叶学友！你认为怎么样，如来死后还存在吗？”</p><p>迦叶尊者说：“舍利弗学友！世尊不会讲解和回答：「如来死后还存在吗？」这个问题。”</p><p>舍利弗尊者说：“那么，迦叶学友！如来死后就不存在了吗？”</p><p>迦叶尊者说：“舍利弗学友！世尊也不会讲解和回答：「如来死后就不存在了吗？」这个问题。”</p><p>舍利弗尊者说：“迦叶学友！那么，如来死后既存在也不存在，是这样的吗？”</p><p>迦叶尊者说：“舍利弗学友！世尊也不会讲解和回答：「如来死后是既存在也不存在吗？」这个问题。”</p><p>舍利弗尊者说：“迦叶学友！如来死后既不存在也不是不存在吗？”</p><p>迦叶尊者说：“舍利弗学友！世尊也不会讲解和回答：「如来死后既不存在也不是不存在吗？」这个问题。”</p><p>舍利弗尊者说：“迦叶学友！为什么世尊不讲解和回答：如来死后的事情呢？”</p><p>迦叶尊者说：“舍利弗学友！因为讲解这些问题无法让世间的人获得功德利益；讲解这些问题无法让世间人学到清净修行的方法；讲解这些问题无法解除世间人对一切事物的挂念和执着；讲解这些问题无法让世间人逐渐的熄灭贪欲、灭尽贪欲；讲解这些问题无法让世间人内心清净安宁；讲解这些问题无法让世间人开启智慧；讲解这些问题无法让世间人证悟无上正等正觉；讲解这些问题无法让世间人达到不生不灭涅槃的境界。所以世尊不讲解和回答这些问题。”</p><p>舍利弗尊者说：“迦叶学友！那么，世尊会讲解什么呢？世尊会回答什么问题呢？”</p><p>迦叶尊者说：“舍利弗学友！世尊会讲解：「为什么出生在世间的众生是非常痛苦的？」，世尊会讲解：「痛苦的根源是什么？痛苦的起因是什么？」，世尊会讲解：「灭除什么才能灭除痛苦？」，世尊会讲解：「灭除痛苦的修行方法是什么？」，世尊会讲解和回答这些问题。”</p><p>舍利弗尊者说：“迦叶学友！为什么世尊要讲解和回答这些问题呢？”</p><p>迦叶尊者说：“舍利弗学友！因为讲解这些问题能够让世间的人获得功德利益；讲解这些问题能够让世间人学到清净修行的方法；讲解这些问题能够解除世间人对一切事物的挂念和执着；讲解这些问题能够让世间人逐渐的熄灭贪欲、灭尽贪欲；讲解这些问题能够让世间人内心清净安宁；讲解这些问题能够让世间人开启智慧；讲解这些问题能够让世间人证悟无上正等正觉；讲解这些问题能够让世间人达到不生不灭涅槃的境界。所以世尊讲解和回答这些问题。”</p><p>迦叶尊者说法后，舍利弗尊者随喜赞叹迦叶尊者说法的无量功德，并按着迦叶尊者所说的法去修行。</p>',18)]))}const f=t(_,[["render",r]]);export{m as __pageData,f as default};
